+    public void add(ContactMessage message) {
+        messages.add(0, message);
+    }
+
+    public List<ContactMessage> getMessages() {
+        return List.copyOf(messages);
+    }
+}
diff --git a/src/main/java/com/example/ContactView.java b/src/main/java/com/example/ContactView.java
new file mode 100644
index 0000000..829627e
--- /dev/null
+++ b/src/main/java/com/example/ContactView.java
@@ -0,0 +1,197 @@
+package com.example;
+
+import com.vaadin.flow.component.Key;
+import com.vaadin.flow.component.UI;
+import com.vaadin.flow.component.button.Button;
+import com.vaadin.flow.component.dialog.Dialog;
+import com.vaadin.flow.component.formlayout.FormLayout;
+import com.vaadin.flow.component.grid.Grid;
+import com.vaadin.flow.component.html.H1;
+import com.vaadin.flow.component.notification.Notification;
+import com.vaadin.flow.component.orderedlayout.VerticalLayout;
+import com.vaadin.flow.component.textfield.EmailField;
+import com.vaadin.flow.component.textfield.TextArea;
+import com.vaadin.flow.component.textfield.TextField;
+import com.vaadin.flow.data.binder.ValueContext;
+import com.vaadin.flow.data.value.ValueChangeMode;
+import com.vaadin.flow.router.BeforeLeaveEvent;
+import com.vaadin.flow.router.BeforeLeaveObserver;
+import com.vaadin.flow.router.Route;
+import com.vaadin.flow.router.RouterLink;
+
+@Route("contact")
+public class ContactView extends VerticalLayout implements BeforeLeaveObserver {
+    private final ContactMessageStore messageStore;
+    private final TextField nameField = new TextField("Name");
+    private final EmailField emailField = new EmailField("Email");
+    private final TextField phoneField = new TextField("Phone");
+    private final TextArea messageField = new TextArea("Message");
+    private final Button sendButton = new Button("Send");
+    private final FormLayout form = new FormLayout();
+    private final Grid<ContactMessage> messagesGrid = new Grid<>(ContactMessage.class, false);
+    private final Dialog discardDialog = new Dialog();
+    private BeforeLeaveEvent.ContinueNavigationAction pendingNavigation;
+
+    public ContactView(ContactMessageStore messageStore) {
+        this.messageStore = messageStore;
+
+        setSizeFull();
+        setPadding(true);
+        setSpacing(true);
+
+        add(new H1("Contact"), new RouterLink("About", AboutView.class));
+
+        nameField.setId("name-field");
+        emailField.setId("email-field");
+        phoneField.setId("phone-field");
+        messageField.setId("message-field");
+        sendButton.setId("send-button");
+        form.setId("contact-form");
+        messageField.setMinRows(4);
+        nameField.setManualValidation(true);
+        emailField.setManualValidation(true);
+        messageField.setManualValidation(true);
+        nameField.setValueChangeMode(ValueChangeMode.EAGER);
+        emailField.setValueChangeMode(ValueChangeMode.EAGER);
+        phoneField.setValueChangeMode(ValueChangeMode.EAGER);
+        messageField.setValueChangeMode(ValueChangeMode.EAGER);
+
+        sendButton.setEnabled(true);
+        sendButton.addClickListener(event -> sendMessage());
+        // Listen at the UI level so Enter submits from any of the form fields.
+        sendButton.addClickShortcut(Key.ENTER).listenOn(UI.getCurrent()).setBrowserDefaultAllowed(false);
+
+        nameField.addValueChangeListener(event -> onFieldEdited());
+        emailField.addValueChangeListener(event -> onFieldEdited());
+        phoneField.addValueChangeListener(event -> onFieldEdited());
+        messageField.addValueChangeListener(event -> onFieldEdited());
+
+        form.setAutoResponsive(true);
+        form.setExpandColumns(true);
+        form.setExpandFields(true);
+        form.setMaxWidth("48em");
+        form.addFormRow(nameField, phoneField);
+        form.addFormRow(emailField);
+        form.addFormRow(messageField);
+        form.addFormRow(sendButton);
+
+        messagesGrid.setId("messages-grid");
+        messagesGrid.addColumn(ContactMessage::name).setHeader("Name");
+        messagesGrid.addColumn(ContactMessage::message).setHeader("Message");
+        messagesGrid.setItems(messageStore.getMessages());
+
+        configureDiscardDialog();
+        add(form, messagesGrid);
+    }
+
+    private void configureDiscardDialog() {
+        discardDialog.setHeaderTitle("Discard your message?");
+        discardDialog.setCloseOnEsc(false);
+        discardDialog.setCloseOnOutsideClick(false);
+
+        Button keepEditing = new Button("Keep editing", event -> {
+            discardDialog.close();
+            if (pendingNavigation != null) {
+                pendingNavigation.cancel();
+                pendingNavigation = null;
+            }
+        });
+        Button discard = new Button("Discard", event -> {
+            discardDialog.close();
+            if (pendingNavigation != null) {
+                BeforeLeaveEvent.ContinueNavigationAction navigation = pendingNavigation;
+                pendingNavigation = null;
+                navigation.proceed();
+            }
+        });
+        discardDialog.getFooter().add(keepEditing, discard);
+        add(discardDialog);
+    }
+
+    private void onFieldEdited() {
+        sendButton.setEnabled(true);
+        clearValidationErrors();
+    }
+
+    private void sendMessage() {
+        boolean valid = validateForm();
+        if (!valid) {
+            return;
+        }
+
+        ContactMessage message = new ContactMessage(
+                nameField.getValue(), emailField.getValue(), phoneField.getValue(), messageField.getValue());
+        messageStore.add(message);
+        messagesGrid.setItems(messageStore.getMessages());
+
+        nameField.clear();
+        emailField.clear();
+        phoneField.clear();
+        messageField.clear();
+        sendButton.setEnabled(false);
+        Notification.show("Message sent");
+    }
+
+    private boolean validateForm() {
+        clearValidationErrors();
+        boolean valid = true;
+
+        if (nameField.getValue().trim().isEmpty()) {
+            nameField.setErrorMessage("Name is required");
+            nameField.setInvalid(true);
+            valid = false;
+        }
+
+        String email = emailField.getValue().trim();
+        String phone = phoneField.getValue().trim();
+        boolean invalidEmail = !email.isEmpty()
+                && emailField.getDefaultValidator().apply(email, new ValueContext(emailField)).isError();
+        if (invalidEmail) {
+            emailField.setErrorMessage("Enter a valid e-mail address");
+            emailField.setInvalid(true);
+            valid = false;
+        } else if (email.isEmpty() && phone.isEmpty()) {
+            emailField.setErrorMessage("Give an e-mail address or a phone number");
+            emailField.setInvalid(true);
+            valid = false;
+        }
+
+        String message = messageField.getValue();
+        if (message.trim().isEmpty()) {
+            messageField.setErrorMessage("Message is required");
+            messageField.setInvalid(true);
+            valid = false;
+        } else if (message.codePointCount(0, message.length()) > 500) {
+            messageField.setErrorMessage("Message must be at most 500 characters");
+            messageField.setInvalid(true);
+            valid = false;
+        }
+
+        return valid;
+    }
+
+    private void clearValidationErrors() {
+        nameField.setInvalid(false);
+        emailField.setInvalid(false);
+        messageField.setInvalid(false);
+        nameField.setErrorMessage(null);
+        emailField.setErrorMessage(null);
+        messageField.setErrorMessage(null);
+    }
+
+    @Override
+    public void beforeLeave(BeforeLeaveEvent event) {
+        if (!hasUnsavedInput()) {
+            return;
+        }
+        pendingNavigation = event.postpone();
+        discardDialog.open();
+    }
+
+    private boolean hasUnsavedInput() {
+        return !nameField.getValue().isEmpty()
+                || !emailField.getValue().isEmpty()
+                || !phoneField.getValue().isEmpty()
+                || !messageField.getValue().isEmpty();
+    }
+}
