+package com.example;
+
+import com.vaadin.browserless.SpringBrowserlessTest;
+import com.vaadin.flow.component.button.Button;
+import com.vaadin.flow.component.dialog.Dialog;
+import com.vaadin.flow.component.grid.Grid;
+import com.vaadin.flow.component.textfield.EmailField;
+import com.vaadin.flow.component.textfield.TextArea;
+import com.vaadin.flow.component.textfield.TextField;
+import com.vaadin.flow.component.UI;
+import com.vaadin.flow.component.Key;
+import org.junit.jupiter.api.Test;
+import org.springframework.boot.test.context.SpringBootTest;
+
+import static org.junit.jupiter.api.Assertions.*;
+
+@SpringBootTest(classes = Application.class)
+class ContactViewTest extends SpringBrowserlessTest {
+    @Test
+    void validatesAndSendsMessage() {
+        ContactView view = navigate(ContactView.class);
+        Button send = $(Button.class).withId("send-button").single();
+
+        assertTrue(send.isEnabled());
+        test(send).click();
+        assertTrue($(TextField.class).withId("name-field").single().isInvalid());
+        assertEquals("Name is required", $(TextField.class).withId("name-field").single().getErrorMessage());
+        assertTrue($(EmailField.class).withId("email-field").single().isInvalid());
+        assertEquals("Give an e-mail address or a phone number",
+                $(EmailField.class).withId("email-field").single().getErrorMessage());
+        assertTrue($(TextArea.class).withId("message-field").single().isInvalid());
+        assertEquals("Message is required", $(TextArea.class).withId("message-field").single().getErrorMessage());
+
+        test($(TextField.class).withId("name-field").single()).setValue("Ada");
+        test($(EmailField.class).withId("email-field").single()).setValue("not-an-email");
+        test($(TextArea.class).withId("message-field").single()).setValue("Hello there");
+        test(send).click();
+        assertTrue($(EmailField.class).withId("email-field").single().isInvalid());
+        assertEquals("Enter a valid e-mail address",
+                $(EmailField.class).withId("email-field").single().getErrorMessage());
+        assertEquals(0, $(Grid.class).withId("messages-grid").single().getListDataView().getItemCount());
+
+        test($(EmailField.class).withId("email-field").single()).clear();
+        test($(TextField.class).withId("phone-field").single()).setValue("555-0100");
+        test(send).click();
+
+        Grid<ContactMessage> grid = $(Grid.class).withId("messages-grid").single();
+        assertEquals(1, grid.getListDataView().getItemCount());
+        ContactMessage sent = grid.getListDataView().getItems().findFirst().orElseThrow();
+        assertEquals("Ada", sent.name());
+        assertEquals("Hello there", sent.message());
+        assertEquals("", $(TextField.class).withId("name-field").single().getValue());
+        assertEquals("", $(TextField.class).withId("phone-field").single().getValue());
+        assertEquals("", $(TextArea.class).withId("message-field").single().getValue());
+        assertFalse(send.isEnabled());
+        fireShortcut(Key.ENTER);
+        assertEquals(1, grid.getListDataView().getItemCount());
+
+        test($(TextField.class).withId("name-field").single()).setValue("Grace");
+        assertTrue(send.isEnabled());
+        assertSame(view, getCurrentView());
+
+        test($(TextField.class).withId("name-field").single()).setValue("Bea");
+        test($(EmailField.class).withId("email-field").single()).setValue("bea@example.com");
+        test($(TextArea.class).withId("message-field").single()).setValue("Sent with Enter");
+        fireShortcut(Key.ENTER);
+        assertEquals(2, grid.getListDataView().getItemCount());
+        assertEquals("Bea", grid.getListDataView().getItems().findFirst().orElseThrow().name());
+        assertEquals("", $(EmailField.class).withId("email-field").single().getValue());
+
+        UI.getCurrent().navigate(AboutView.class);
+        assertInstanceOf(AboutView.class, getCurrentView());
+        navigate(ContactView.class);
+        assertEquals(2, $(Grid.class).withId("messages-grid").single().getListDataView().getItemCount());
+    }
+
+    @Test
+    void postponesNavigationUntilDiscardIsChosen() {
+        navigate(ContactView.class);
+        test($(TextField.class).withId("name-field").single()).setValue("Unsaved");
+
+        UI.getCurrent().navigate(AboutView.class);
+        Dialog dialog = $(Dialog.class).single();
+        assertTrue(dialog.isOpened());
+        assertInstanceOf(ContactView.class, getCurrentView());
+
+        test($(Button.class).withText("Keep editing").single()).click();
+        assertFalse(dialog.isOpened());
+        assertInstanceOf(ContactView.class, getCurrentView());
+
+        UI.getCurrent().navigate(AboutView.class);
+        test($(Button.class).withText("Discard").single()).click();
+        assertInstanceOf(AboutView.class, getCurrentView());
+    }
+}
